      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have created a decisive new level of frequency metrology, enabling tests and measurements that were previously inaccessible.",
        "attribution": "Katori's magic-wavelength lattice-clock concept and Ye's foundational experimental development form a clear, complementary attribution.",
        "maturity": "The technology has been repeatedly demonstrated at exceptional precision and has become a broadly enabling measurement platform.",
        "uncertainties": [
          "The eventual scale of applications beyond fundamental metrology remains developing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Carlton M. Caves",
        "Nergis Mavalvala",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light turned a quantum limit on measurement into a practical route to greater sensitivity, with major consequences for precision experiments.",
        "attribution": "Caves supplied the central quantum-measurement insight, while Mavalvala and Schnabel represent decisive experimental realization and deployment.",
        "maturity": "Squeezing is now a reproducible operational technique in demanding interferometric measurements.",
        "uncertainties": [
          "Credit is distributed across a substantial community of theorists and experimentalists."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry established matter waves as exceptionally sensitive instruments for inertial, gravitational, and fundamental measurements.",
        "attribution": "Bordé made foundational contributions to light-pulse atom interferometry and Kasevich demonstrated its powerful precision-measurement implementation.",
        "maturity": "The field has achieved robust laboratory and field demonstrations across multiple measurement modalities.",
        "uncertainties": [
          "The relative credit of several early contributors requires careful historical resolution."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Paul B. Corkum",
        "Maciej Lewenstein",
        "Kenneth J. Schafer"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision framework made high-harmonic generation intelligible and underpinned the emergence of attosecond science.",
        "attribution": "Corkum, Lewenstein, and Schafer made distinct central theoretical contributions to the physical picture and its quantitative theory.",
        "maturity": "The ideas have been extensively tested and have enabled a mature experimental discipline.",
        "uncertainties": [
          "Experimental pioneers in high-harmonic and attosecond generation also have substantial claims to recognition."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Philip St. J. Russell",
        "Jonathan C. Knight",
        "Timothy A. Birks"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystal fibre reshaped the control of light in fibres and became an enabling platform for nonlinear optics, sensing, and ultrafast science.",
        "attribution": "Russell's concept and the key fibre demonstrations and development by Knight and Birks offer a coherent attribution.",
        "maturity": "The platform has long since passed from a laboratory novelty to widely used optical technology.",
        "uncertainties": [
          "The contribution is partly an invention and technology platform rather than a single fundamental discovery."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B060",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Evgeny Saldin",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "SASE X-ray free-electron lasers opened an unprecedented source regime for ultrafast structural and dynamical measurements.",
        "attribution": "Pellegrini, Saldin, and Kim made central complementary contributions to the physical concept and realization of SASE FELs.",
        "maturity": "Large-scale facilities have delivered reproducible scientific capability and broad impact across physics, chemistry, and biology.",
        "uncertainties": [
          "Facility construction and realization involved many indispensable contributors."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B062",
      "proposed_laureates": [
        "Harald Rose",
        "Maximilian Haider",
        "Knut Urban"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration correction transformed electron microscopy into a substantially more powerful quantitative probe of matter.",
        "attribution": "Rose provided key theoretical foundations, while Haider and Urban were central to practical correction and its materials-science validation.",
        "maturity": "The method is established in advanced microscopy and has enabled direct observation at atomic scales.",
        "uncertainties": [
          "The development path includes several closely related corrector concepts and teams."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Gerald Gabrielse",
        "Jeffrey Hangst",
        "Stefan Ulmer"
      ],
      "assessment": {
        "nobel_worthiness": "Cold-antimatter trapping and precision comparisons offer uniquely clean tests of fundamental symmetries using experimentally controlled antimatter.",
        "attribution": "Gabrielse, Hangst, and Ulmer represent central advances in trapping, spectroscopy, and precision antimatter measurements.",
        "maturity": "The experimental control has progressed impressively, though the ultimate precision programme remains active.",
        "uncertainties": [
          "No deviation from CPT symmetry has been established.",
          "The allocation of credit among collaborative antimatter programmes is complex."
        ]
      }
    }
  ]
